 "content": "def transform(grid):
    """Draw an 8-colored parallel trail just beyond the non-background object beside a straight 2-line."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg, line_color, trail_color = 5, 2, 8

    # Find the full straight 2-line (vertical or horizontal).
    line = None
    for c in range(w):
        if all(g[r][c] == line_color for r in range(h)):
            line = ("v", c)
            break
    if line is None:
        for r in range(h):
            if all(g[r][c] == line_color for c in range(w)):
                line = ("h", r)
                break
    if line is None:
        return g

    orientation, pos = line
    obj = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] not in (bg, line_color)]
    if not obj:
        return g

    if orientation == "v":
        side = 1 if max(c for r, c in obj) > pos else -1
        edge = max(c for r, c in obj) if side > 0 else min(c for r, c in obj)
        trail_c = edge + side
        if 0 <= trail_c < w:
            for r in range(h):
                g[r][trail_c] = trail_color
    else:
        side = 1 if max(r for r, c in obj) > pos else -1
        edge = max(r for r, c in obj) if side > 0 else min(r for r, c in obj)
        trail_r = edge + side
        if 0 <= trail_r < h:
            g[trail_r] = [trail_color] * w
    return g
